const DEFAULT_SIGNALING_FALLBACK = (() => { try { const c = window.__ETHER_CONFIG__; return c && c.servers && c.servers[0] && c.servers[0].url || "wss://ether-1-baqy.onrender.com"; } catch (e) { return "wss://ether-1-baqy.onrender.com"; } })();

